import ast,base64,hashlib,json,os,platform,resource,signal,stat,sys,time,traceback,types
from pathlib import Path
started=time.monotonic()
resource.setrlimit(resource.RLIMIT_CPU,(90,90))
resource.setrlimit(resource.RLIMIT_AS,(1<<30,1<<30))
resource.setrlimit(resource.RLIMIT_CORE,(0,0))
signal.alarm(180)
assert sys.version_info[:3]==(3,12,14)
root=Path("/workspace/scratch/9acdfa9f5639/native-checker-development/physical-after-r1")
out=Path("/workspace/scratch/9acdfa9f5639/native-checker-development/local-evidence/physical-after-AST-r1")
out.mkdir(parents=True,exist_ok=False)
rows=json.loads(base64.b64decode(""))
prefix="review-evidence/hia-native-rewrite-20261111/remote-recovery-r3/backend-physical-after-r1/"
report={"status":"INCOMPLETE","scope":"LOCAL_SOURCE_AST_AND_TEXT_INVERSE_ONLY","parent_delivery":"43210ebe3e446f5c8864f5c6fc072abea5ea15e3","python":sys.version,"platform":platform.platform(),"libc":list(platform.libc_ver()),"official_Ubuntu_qualification":False,"HIA_generation":0,"B3":0,"C_compilation":0,"VM":0,"native":0,"rows":[],"failures":[]}
before={}
for row in rows:
    path=root/row["path"][len(prefix):]
    raw=path.read_bytes()
    observed={"bytes":len(raw),"sha256":hashlib.sha256(raw).hexdigest(),"gitsha":hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\0"+raw).hexdigest(),"mode":format(stat.S_IMODE(path.stat().st_mode),"06o")}
    assert observed["mode"]=="000644" and not path.is_symlink()
    assert all(observed[k]==row[k] for k in ("bytes","sha256","gitsha"))
    before[str(path)]=raw
    item=dict(path=str(path),gitsha=row["gitsha"],sha256=row["sha256"],bytes=len(raw),mode="100644",active_python=row["active_python"])
    if row["active_python"]:
        try:
            ast.parse(raw,filename=str(path))
            item["AST"]="PASS"
        except BaseException as error:
            item.update(AST="FAIL",error=repr(error),traceback=traceback.format_exc())
            report["failures"].append(item)
    report["rows"].append(item)
try:
    ci_path=root/"ci/backend_physical_after_ci.py"
    module=types.ModuleType("physical_after_local_source_checks");module.__file__=str(ci_path)
    exec(compile(ci_path.read_bytes(),str(ci_path),"exec"),module.__dict__)
    report["text_transform_checks"]=module.source_transform_readback(root)
    old_path=root/"reference/backend_join_ci_reference.py"
    prior=types.ModuleType("physical_after_prior_static");prior.__file__=str(old_path)
    exec(compile(old_path.read_bytes(),str(old_path),"exec"),prior.__dict__)
    prior.file_closure(root)
    report["prior_source_closure"]="PASS"
except BaseException as error:
    report["failures"].append(dict(scope="source_inverse_and_closure",error=repr(error),traceback=traceback.format_exc()))
for name,raw in before.items():
    assert Path(name).read_bytes()==raw and stat.S_IMODE(Path(name).stat().st_mode)==0o644
report["source_after_equal"]=True
report["counts"]={"source_files":len(rows),"active_python":sum(r["active_python"] for r in rows),"AST_PASS":sum(r.get("AST")=="PASS" for r in report["rows"]),"AST_FAIL":sum(r.get("AST")=="FAIL" for r in report["rows"]),"source_bytes":sum(r["bytes"] for r in rows)}
usage=resource.getrusage(resource.RUSAGE_SELF)
report["CPU_seconds"]=usage.ru_utime+usage.ru_stime
report["wall_seconds"]=time.monotonic()-started
report["limits"]={"CPU":list(resource.getrlimit(resource.RLIMIT_CPU)),"AS":list(resource.getrlimit(resource.RLIMIT_AS)),"CORE":list(resource.getrlimit(resource.RLIMIT_CORE)),"wall":180}
if report["CPU_seconds"]>=90 or report["wall_seconds"]>=180:report["failures"].append({"scope":"budget","error":"original source check90/180"})
report["status"]="PASS" if not report["failures"] else "FAIL"
raw=json.dumps(report,sort_keys=True,indent=2)+"\n"
(out/"source-audit.json").write_text(raw)
print(raw,end="",flush=True)
if report["status"]!="PASS":raise SystemExit(1)
